    CATEGORY_LABELSVectorOffset CATEGORY_LABELS: Offset = Offset(),
    DTYPE: agfDType = .unspecified,
    FILL_VALUE: Double = 0.0,
    SCALE_FACTOR: Double = 1.0,
    ADD_OFFSET: Double = 0.0,
    NX: UInt32 = 0,
    NY: UInt32 = 0,
    ROW_ORDER: agfRowOrder = .unspecified,
    PROJECTION: agfProjection = .unspecified,
    PROJECTION_PARAMETERSOffset PROJECTION_PARAMETERS: Offset,
    PAYLOAD_CODEC: agfPayloadCodec = .unspecified,
    PAYLOADVectorOffset PAYLOAD: Offset = Offset(),
    PAYLOAD_CIDOffset PAYLOAD_CID: Offset = Offset(),
    PAYLOAD_SHA256Offset PAYLOAD_SHA256: Offset,
    PAYLOAD_SIZE_BYTES: UInt64 = 0,
    PROVENANCEOffset PROVENANCE: Offset,
    DESCRIPTIONOffset DESCRIPTION: Offset = Offset()
  ) -> Offset {
    let __start = AGF.startAGF(&fbb)
    AGF.add(ID: ID, &fbb)
    AGF.add(EPOCH: EPOCH, &fbb)
    AGF.add(VALID_START: VALID_START, &fbb)
    AGF.add(VALID_END: VALID_END, &fbb)
    AGF.add(FORECAST_REFERENCE_TIME: FORECAST_REFERENCE_TIME, &fbb)
    AGF.add(FORECAST_LEAD_S: FORECAST_LEAD_S, &fbb)
    AGF.add(VARIABLE: VARIABLE, &fbb)
    AGF.add(UNITS: UNITS, &fbb)
    AGF.addVectorOf(CATEGORY_LABELS: CATEGORY_LABELS, &fbb)
    AGF.add(DTYPE: DTYPE, &fbb)
    AGF.add(FILL_VALUE: FILL_VALUE, &fbb)
    AGF.add(SCALE_FACTOR: SCALE_FACTOR, &fbb)
    AGF.add(ADD_OFFSET: ADD_OFFSET, &fbb)
    AGF.add(NX: NX, &fbb)
    AGF.add(NY: NY, &fbb)
    AGF.add(ROW_ORDER: ROW_ORDER, &fbb)
    AGF.add(PROJECTION: PROJECTION, &fbb)
    AGF.add(PROJECTION_PARAMETERS: PROJECTION_PARAMETERS, &fbb)
    AGF.add(PAYLOAD_CODEC: PAYLOAD_CODEC, &fbb)
    AGF.addVectorOf(PAYLOAD: PAYLOAD, &fbb)
    AGF.add(PAYLOAD_CID: PAYLOAD_CID, &fbb)
    AGF.add(PAYLOAD_SHA256: PAYLOAD_SHA256, &fbb)
    AGF.add(PAYLOAD_SIZE_BYTES: PAYLOAD_SIZE_BYTES, &fbb)
    AGF.add(PROVENANCE: PROVENANCE, &fbb)
    AGF.add(DESCRIPTION: DESCRIPTION, &fbb)
    return AGF.endAGF(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.ID, fieldName: "ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.EPOCH, fieldName: "EPOCH", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.VALID_START, fieldName: "VALID_START", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.VALID_END, fieldName: "VALID_END", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.FORECAST_REFERENCE_TIME, fieldName: "FORECAST_REFERENCE_TIME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.FORECAST_LEAD_S, fieldName: "FORECAST_LEAD_S", required: false, type: Double.self)
    try _v.visit(field: VT.VARIABLE, fieldName: "VARIABLE", required: false, type: agfVariable.self)
    try _v.visit(field: VT.UNITS, fieldName: "UNITS", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.CATEGORY_LABELS, fieldName: "CATEGORY_LABELS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.DTYPE, fieldName: "DTYPE", required: false, type: agfDType.self)
    try _v.visit(field: VT.FILL_VALUE, fieldName: "FILL_VALUE", required: false, type: Double.self)
    try _v.visit(field: VT.SCALE_FACTOR, fieldName: "SCALE_FACTOR", required: false, type: Double.self)
    try _v.visit(field: VT.ADD_OFFSET, fieldName: "ADD_OFFSET", required: false, type: Double.self)
    try _v.visit(field: VT.NX, fieldName: "NX", required: false, type: UInt32.self)
    try _v.visit(field: VT.NY, fieldName: "NY", required: false, type: UInt32.self)
    try _v.visit(field: VT.ROW_ORDER, fieldName: "ROW_ORDER", required: false, type: agfRowOrder.self)
    try _v.visit(field: VT.PROJECTION, fieldName: "PROJECTION", required: false, type: agfProjection.self)
    try _v.visit(field: VT.PROJECTION_PARAMETERS, fieldName: "PROJECTION_PARAMETERS", required: true, type: ForwardOffset<AGFProjectionParameters>.self)
    try _v.visit(field: VT.PAYLOAD_CODEC, fieldName: "PAYLOAD_CODEC", required: false, type: agfPayloadCodec.self)
    try _v.visit(field: VT.PAYLOAD, fieldName: "PAYLOAD", required: false, type: ForwardOffset<Vector<UInt8, UInt8>>.self)
    try _v.visit(field: VT.PAYLOAD_CID, fieldName: "PAYLOAD_CID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PAYLOAD_SHA256, fieldName: "PAYLOAD_SHA256", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PAYLOAD_SIZE_BYTES, fieldName: "PAYLOAD_SIZE_BYTES", required: false, type: UInt64.self)
    try _v.visit(field: VT.PROVENANCE, fieldName: "PROVENANCE", required: true, type: ForwardOffset<AGFProvenance>.self)
    try _v.visit(field: VT.DESCRIPTION, fieldName: "DESCRIPTION", required: false, type: ForwardOffset<String>.self)
    _v.finish()
  }
